export default [["q-fcps-bio4-01","Which molecule is the most potent allosteric activator of phosphofructokinase-1?",["Fructose 2,6-bisphosphate","Citrate","ATP","Glucagon"],"Fructose 2,6-bisphosphate, made by PFK-2 under insulin, activates PFK-1 and inhibits fructose 1,6-bisphosphatase."],["q-fcps-bio4-02","A child has severe lactic acidosis and neurological deterioration. Pyruvate dehydrogenase deficiency is suspected. Which dietary change helps?",["High-fat, low-carbohydrate (ketogenic) diet","High-carbohydrate diet","High-protein with leucine","Fructose supplementation"],"Pyruvate cannot enter the TCA cycle, so avoiding carbohydrate reduces lactate. Ketones provide acetyl-CoA directly, and lysine and leucine are purely ketogenic."],["q-fcps-bio4-03","Which inhibitor of the electron transport chain blocks complex I?",["Rotenone","Antimycin A","Cyanide","Oligomycin"],"Rotenone inhibits NADH-coenzyme Q oxidoreductase. Antimycin A blocks complex III, cyanide and carbon monoxide block complex IV, and oligomycin blocks ATP synthase."],["q-fcps-bio4-04","Oligomycin inhibits oxidative phosphorylation by:",["Blocking the proton channel of ATP synthase","Inhibiting complex IV","Dissipating the proton gradient","Inhibiting the adenine nucleotide translocase only"],"Oligomycin binds the F0 subunit, so protons cannot flow back and electron transport stalls because the gradient builds up."],["q-fcps-bio4-05","Thermogenin (UCP1) in brown adipose tissue produces heat by:",["Dissipating the proton gradient across the inner mitochondrial membrane","Inhibiting complex III","Stimulating ATP synthase","Increasing glycolysis"],"UCP1 provides a proton leak that uncouples respiration from ATP synthesis and releases energy as heat, which is important in neonates."],["q-fcps-bio4-06","Which glucose transporter is insulin-dependent?",["GLUT4","GLUT1","GLUT2","GLUT3"],"GLUT4 in skeletal muscle and adipose tissue moves to the membrane in response to insulin. GLUT2 is in the liver, pancreatic beta cells and kidney."],["q-fcps-bio4-07","Which transporter allows pancreatic beta cells to sense glucose?",["GLUT2","GLUT4","SGLT1","GLUT5"],"GLUT2 is a high-capacity, low-affinity transporter, so intracellular glucose follows plasma levels and drives insulin release."],["q-fcps-bio4-08","Which enzyme is activated by cAMP-dependent phosphorylation to promote glycogen breakdown?",["Phosphorylase kinase, activating glycogen phosphorylase","Glycogen synthase","Protein phosphatase 1","Branching enzyme"],"Glucagon and adrenaline raise cAMP and activate protein kinase A, which phosphorylates phosphorylase kinase and in turn glycogen phosphorylase, while inactivating glycogen synthase."],["q-fcps-bio4-09","McArdle disease results from deficiency of:",["Muscle glycogen phosphorylase","Glucose-6-phosphatase","Acid alpha-glucosidase","Debranching enzyme"],"Muscle glycogen cannot be broken down, causing exercise intolerance with a second-wind phenomenon and no rise in lactate."],["q-fcps-bio4-10","Cori disease (type III glycogen storage disease) is caused by deficiency of:",["Debranching enzyme","Branching enzyme","Glucose-6-phosphatase","Lysosomal acid maltase"],"Absent debranching enzyme leaves limit dextrins, and gluconeogenesis is intact, so hypoglycaemia is milder than in von Gierke disease."],["q-fcps-bio4-11","Which enzyme of the urea cycle is the committed regulated step and is activated by N-acetylglutamate?",["Carbamoyl phosphate synthetase I","Ornithine transcarbamylase","Arginase","Argininosuccinate synthetase"],"CPS-I in mitochondria is activated allosterically by N-acetylglutamate, which rises when amino acid catabolism increases."],["q-fcps-bio4-12","Sodium benzoate and sodium phenylbutyrate are used in hyperammonaemia because they:",["Provide alternative pathways for nitrogen excretion","Inhibit glutaminase","Stimulate the urea cycle enzymes","Increase renal ammonia reabsorption"],"Benzoate conjugates with glycine and phenylacetate with glutamine, forming compounds that are excreted in urine and carry away nitrogen."],["q-fcps-bio4-13","Which amino acid disorder presents with a musty odour, fair skin and intellectual disability if untreated?",["Phenylketonuria","Maple syrup urine disease","Homocystinuria","Alkaptonuria"],"Phenylalanine hydroxylase or tetrahydrobiopterin deficiency causes phenylalanine accumulation, so tyrosine becomes essential and melanin is reduced."],["q-fcps-bio4-14","Which enzyme is rate-limiting in catecholamine synthesis?",["Tyrosine hydroxylase","DOPA decarboxylase","Dopamine beta-hydroxylase","Phenylethanolamine N-methyltransferase"],"Tyrosine hydroxylase is inhibited by dopamine and noradrenaline through end-product feedback."],["q-fcps-bio4-15","Vitamin B6 is required as a coenzyme for:",["Transamination and decarboxylation reactions","Carboxylation reactions","One-carbon transfer","Hydroxylation of proline"],"Pyridoxal phosphate is the coenzyme for aminotransferases, GABA and serotonin synthesis, haem synthesis and glycogen phosphorylase."],["q-fcps-bio4-16","Isoniazid causes peripheral neuropathy by depleting:",["Pyridoxine (vitamin B6)","Thiamine","Niacin","Riboflavin"],"Isoniazid binds pyridoxal and increases its excretion, so pyridoxine is given prophylactically."],["q-fcps-bio4-17","Which is the rate-limiting enzyme of haem synthesis in the liver?",["ALA synthase","ALA dehydratase","Ferrochelatase","Porphobilinogen deaminase"],"ALA synthase requires pyridoxal phosphate and is repressed by haem and induced by barbiturates and other drugs in acute porphyrias."],["q-fcps-bio4-18","Crigler-Najjar syndrome type I is caused by absence of:",["UDP-glucuronosyltransferase 1A1","Haem oxygenase","Biliverdin reductase","Bilirubin oxidase"],"Without conjugation, unconjugated bilirubin accumulates and can cause kernicterus. Gilbert syndrome is a mild reduction of the same enzyme."],["q-fcps-bio4-19","A patient has raised conjugated bilirubin, a black liver on biopsy and normal liver enzymes. The diagnosis is:",["Dubin-Johnson syndrome","Gilbert syndrome","Rotor syndrome","Crigler-Najjar type II"],"Dubin-Johnson syndrome is a defect of MRP2 canalicular export, giving conjugated hyperbilirubinaemia and a pigmented liver."],["q-fcps-bio4-20","Which hormone is the master regulator of iron absorption and is raised in inflammation?",["Hepcidin","Erythropoietin","Transferrin","Ferritin"],"Hepcidin blocks ferroportin, trapping iron in enterocytes and macrophages and causing the anaemia of chronic disease."],["q-fcps-bio4-21","Wilson disease is characterised by:",["Low serum ceruloplasmin and raised urinary copper","High serum ceruloplasmin","Low urinary copper","Iron overload"],"ATP7B deficiency impairs biliary copper excretion and ceruloplasmin incorporation, causing hepatic, neurological and corneal copper deposition."],["q-fcps-bio4-22","Menkes disease results from a mutation in the gene for a copper-transporting ATPase. Which enzyme is deficient, producing kinky hair?",["Lysyl oxidase","Prolyl hydroxylase","Tyrosinase only","Superoxide dismutase only"],"Reduced copper impairs lysyl oxidase and cross-linking of collagen and elastin, with neurodegeneration and brittle hair."],["q-fcps-bio4-23","Which vitamin is a lipid-soluble antioxidant protecting red cell membranes?",["Vitamin E","Vitamin C","Vitamin K","Vitamin D"],"Tocopherol stops lipid peroxidation, and deficiency causes haemolytic anaemia and neuropathy, especially in fat malabsorption."],["q-fcps-bio4-24","Retinoic acid acts as a:",["Ligand for nuclear receptors regulating gene transcription","Visual pigment","Coenzyme in carboxylation","Cofactor in collagen synthesis"],"Retinoic acid binds RAR and RXR receptors and controls differentiation of epithelia, while retinal is the visual chromophore."],["q-fcps-bio4-25","Which vitamin deficiency causes megaloblastic anaemia WITHOUT neurological signs?",["Folate","Vitamin B12","Vitamin B6","Vitamin C"],"Folate deficiency impairs thymidylate synthesis, but only B12 deficiency causes demyelination through methylmalonyl-CoA accumulation."],["q-fcps-bio4-26","Methotrexate inhibits which enzyme?",["Dihydrofolate reductase","Thymidylate synthase","Ribonucleotide reductase","Xanthine oxidase"],"Methotrexate blocks regeneration of tetrahydrofolate, so purine and thymidylate synthesis falls."],["q-fcps-bio4-27","Biotin is a coenzyme for which enzyme?",["Pyruvate carboxylase","Pyruvate dehydrogenase","Transketolase","Glutathione reductase"],"Biotin-dependent carboxylases include pyruvate carboxylase, acetyl-CoA carboxylase and propionyl-CoA carboxylase."],["q-fcps-bio4-28","Which enzyme converts homocysteine to methionine and needs vitamin B12?",["Methionine synthase","Cystathionine beta-synthase","Methylmalonyl-CoA mutase","Serine hydroxymethyltransferase"],"Methionine synthase transfers a methyl group from methyltetrahydrofolate, so B12 deficiency traps folate and raises homocysteine."],["q-fcps-bio4-29","Methylmalonic aciduria is typical of which deficiency?",["Vitamin B12","Folate","Thiamine","Vitamin B6"],"Methylmalonyl-CoA mutase requires adenosylcobalamin, so methylmalonic acid is raised only in B12 deficiency."],["q-fcps-bio4-30","Familial type III hyperlipoproteinaemia (dysbetalipoproteinaemia) is associated with a defect in:",["Apolipoprotein E","Lipoprotein lipase","LDL receptor","Apolipoprotein A-I"],"Abnormal ApoE2 impairs hepatic uptake of chylomicron and VLDL remnants, causing palmar xanthomas and raised cholesterol and triglycerides."],["q-fcps-bio4-31","Chylomicronaemia with eruptive xanthomas and pancreatitis in a child is typical of:",["Lipoprotein lipase or ApoC-II deficiency","LDL receptor defect","ApoB-100 defect","Tangier disease"],"Without lipoprotein lipase activity chylomicrons accumulate, plasma is milky and triglycerides are extremely high."],["q-fcps-bio4-32","Abetalipoproteinaemia is caused by a defect in:",["Microsomal triglyceride transfer protein","Lipoprotein lipase","LCAT","ABCA1"],"Without apoB-containing lipoprotein assembly, patients have fat malabsorption, acanthocytes and deficiencies of fat-soluble vitamins."],["q-fcps-bio4-33","Tangier disease is due to a defect in:",["ABCA1 cholesterol efflux transporter","LCAT","CETP","Hepatic lipase"],"Defective ABCA1 reduces HDL and cholesterol accumulates in macrophages, giving orange tonsils and neuropathy."],["q-fcps-bio4-34","Which lipid storage disease causes a cherry-red macula and sphingomyelin accumulation with hepatosplenomegaly?",["Niemann-Pick disease","Tay-Sachs disease","Fabry disease","Krabbe disease"],"Niemann-Pick disease is deficiency of sphingomyelinase, with foam cells and neurodegeneration. Unlike Tay-Sachs it causes organomegaly."],["q-fcps-bio4-35","Globoid cells and absence of myelin with irritability and developmental regression in an infant suggest deficiency of:",["Galactocerebrosidase","Arylsulfatase A","Hexosaminidase A","Beta-glucosidase"],"Krabbe disease results from galactocerebrosidase deficiency, with accumulation of psychosine that destroys oligodendrocytes."],["q-fcps-bio4-36","Hurler syndrome is a mucopolysaccharidosis caused by deficiency of:",["Alpha-L-iduronidase","Iduronate sulfatase","Heparan sulfamidase","Beta-glucuronidase"],"Hurler syndrome has corneal clouding, coarse features and developmental delay. Hunter syndrome (X-linked iduronate sulfatase deficiency) has no corneal clouding."],["q-fcps-bio4-37","I-cell disease is caused by failure of:",["Phosphorylation of mannose residues on lysosomal enzymes","Glycosylation of collagen","Degradation of glycosaminoglycans","Peroxisomal import"],"Lack of mannose 6-phosphate tagging sends lysosomal enzymes out of the cell, so inclusion bodies accumulate in fibroblasts."],["q-fcps-bio4-38","Zellweger syndrome is a disorder of which organelle?",["Peroxisome","Lysosome","Mitochondrion","Golgi apparatus"],"Peroxisomal biogenesis failure causes accumulation of very long chain fatty acids, hypotonia and liver disease."],["q-fcps-bio4-39","Carnitine is required for:",["Transport of long-chain fatty acids into mitochondria","Fatty acid synthesis","Ketone body synthesis","Cholesterol synthesis"],"Carnitine palmitoyltransferase I is the regulated step, inhibited by malonyl-CoA."],["q-fcps-bio4-40","Which deficiency causes salt wasting, ambiguous genitalia in a girl and raised 17-hydroxyprogesterone?",["21-hydroxylase","11-beta-hydroxylase","17-alpha-hydroxylase","3-beta-hydroxysteroid dehydrogenase"],"21-hydroxylase deficiency blocks cortisol and aldosterone and diverts precursors to androgens."],["q-fcps-bio4-41","11-beta-hydroxylase deficiency produces virilisation with:",["Hypertension","Hypotension","Hypokalaemia with hypotension","Hyperkalaemia"],"Accumulated 11-deoxycorticosterone has mineralocorticoid activity, causing hypertension and hypokalaemia."],["q-fcps-bio4-42","Adenosine deaminase deficiency causes:",["Severe combined immunodeficiency","Gout","Megaloblastic anaemia","Orotic aciduria"],"Accumulation of deoxyadenosine and dATP is toxic to lymphocytes, impairing both T and B cell development."],["q-fcps-bio4-43","A child has megaloblastic anaemia and orotic aciduria without hyperammonaemia. The defect is in:",["UMP synthase","Ornithine transcarbamylase","Dihydrofolate reductase","Thymidylate synthase"],"Hereditary orotic aciduria is a defect of pyrimidine synthesis and responds to uridine. In OTC deficiency orotic acid is raised with hyperammonaemia."],["q-fcps-bio4-44","Which enzyme is inhibited by hydroxyurea?",["Ribonucleotide reductase","Dihydrofolate reductase","Xanthine oxidase","Thymidylate synthase"],"Ribonucleotide reductase converts ribonucleotides to deoxyribonucleotides, so inhibition lowers dNTP pools for DNA synthesis."],["q-fcps-bio4-45","Which DNA repair pathway is defective in hereditary non-polyposis colorectal cancer (Lynch syndrome)?",["Mismatch repair","Nucleotide excision repair","Base excision repair","Homologous recombination"],"Mutations in MLH1, MSH2, MSH6 or PMS2 cause microsatellite instability."],["q-fcps-bio4-46","Which enzyme relieves supercoiling during DNA replication and is targeted by fluoroquinolones in bacteria?",["Topoisomerase II (DNA gyrase)","Helicase","Primase","DNA ligase"],"Gyrase introduces negative supercoils and quinolones trap the enzyme-DNA complex."],["q-fcps-bio4-47","Which feature of the genetic code explains that several codons can code for the same amino acid?",["Degeneracy","Universality","Non-overlapping","Commaless"],"Most amino acids have more than one codon, often differing at the third (wobble) position."],["q-fcps-bio4-48","A point mutation that changes a codon to a stop codon is called:",["Nonsense mutation","Missense mutation","Silent mutation","Frameshift mutation"],"A nonsense mutation causes premature termination and usually a truncated, non-functional protein."],["q-fcps-bio4-49","Deletion of three nucleotides in a coding sequence, as in the commonest cystic fibrosis mutation, leads to:",["Loss of one amino acid without a frameshift","A frameshift","A nonsense codon","Silent change"],"Deletion of a multiple of three nucleotides removes amino acids but preserves the reading frame."],["q-fcps-bio4-50","Fragile X syndrome is caused by expansion of which trinucleotide repeat?",["CGG","CAG","GAA","CTG"],"CGG repeats in FMR1 lead to methylation and silencing. Huntington is CAG, Friedreich ataxia is GAA and myotonic dystrophy is CTG."],["q-fcps-bio4-51","Prader-Willi syndrome results from loss of function of the:",["Paternal copy of chromosome 15q11-13","Maternal copy of chromosome 15q11-13","Paternal chromosome 7","X chromosome"],"It is caused by paternal deletion or maternal uniparental disomy. Loss of the maternal copy causes Angelman syndrome."],["q-fcps-bio4-52","Leber hereditary optic neuropathy shows which pattern of inheritance?",["Mitochondrial (maternal)","Autosomal dominant","X-linked recessive","Autosomal recessive"],"Mitochondrial DNA is inherited from the mother, so all children of an affected mother can carry the mutation."],["q-fcps-bio4-53","In a population in Hardy-Weinberg equilibrium the carrier frequency of an autosomal recessive disease with incidence 1 in 10,000 is about:",["1 in 50","1 in 100","1 in 10","1 in 500"],"q squared is 1 in 10,000, so q is 1 in 100 and 2pq is about 2 in 100, which is 1 in 50."],["q-fcps-bio4-54","The Southern blot is used to detect:",["DNA","RNA","Proteins","Lipids"],"Southern blotting detects DNA, Northern blotting detects RNA and Western blotting detects proteins."],["q-fcps-bio4-55","Which technique amplifies a specific DNA sequence?",["Polymerase chain reaction","Western blot","ELISA","Flow cytometry"],"PCR uses repeated cycles of denaturation, annealing and extension with a heat-stable polymerase."],["q-fcps-bio4-56","The Km of an enzyme is the:",["Substrate concentration at half of maximal velocity","Maximal velocity","Substrate concentration at maximal velocity","Inhibitor concentration at half-maximal inhibition"],"A low Km indicates high affinity for the substrate."],["q-fcps-bio4-57","A competitive inhibitor on a Lineweaver-Burk plot:",["Increases Km without changing Vmax","Decreases Vmax without changing Km","Decreases both Km and Vmax","Increases Vmax"],"Competitive inhibition can be overcome by raising substrate, so the apparent Km increases and the lines intersect on the y axis."],["q-fcps-bio4-58","Which isoenzyme of lactate dehydrogenase is predominant in the heart?",["LDH-1","LDH-5","LDH-3","LDH-2 only"],"LDH-1 (H4) predominates in cardiac muscle and red cells, and LDH-5 (M4) in liver and skeletal muscle."],["q-fcps-bio4-59","The protein structure that is stabilised mainly by hydrogen bonds between backbone atoms is the:",["Secondary structure","Primary structure","Tertiary structure","Quaternary structure"],"Alpha helices and beta sheets are held by backbone hydrogen bonds."],["q-fcps-bio4-60","Prion diseases involve conversion of a protein from a predominantly:",["Alpha helix to beta sheet","Beta sheet to alpha helix","Random coil to alpha helix","Disulphide-bonded to reduced form"],"PrP-sc is rich in beta sheet, is protease resistant and templates conversion of normal PrP-c."],["q-fcps-bio4-61","Cholera toxin causes diarrhoea by:",["ADP-ribosylating Gs and keeping adenylyl cyclase permanently active","ADP-ribosylating Gi","Inhibiting Na-K-ATPase","Blocking chloride channels directly"],"Raised cAMP opens the CFTR channel and causes secretion of chloride and water. Pertussis toxin inactivates Gi."],["q-fcps-bio4-62","Which second messenger is generated from PIP2 by phospholipase C and releases calcium from the endoplasmic reticulum?",["IP3","DAG","cAMP","cGMP"],"IP3 binds receptors on the endoplasmic reticulum, and DAG activates protein kinase C."],["q-fcps-bio4-63","Nitric oxide is synthesised from:",["Arginine","Glutamine","Tyrosine","Tryptophan"],"Nitric oxide synthase converts arginine to citrulline and NO, which activates guanylyl cyclase and raises cGMP."],["q-fcps-bio4-64","During prolonged fasting for more than 3 days the brain obtains most of its energy from:",["Ketone bodies","Glucose","Free fatty acids","Amino acids"],"Ketones cross the blood-brain barrier and spare glucose and muscle protein."],["q-fcps-bio4-65","Which enzyme in the liver is responsible for the first step of ethanol oxidation?",["Alcohol dehydrogenase","Aldehyde dehydrogenase","CYP2E1 only","Catalase only"],"Alcohol dehydrogenase converts ethanol to acetaldehyde with production of NADH, which promotes lactic acidosis, hypoglycaemia and fatty liver."],["q-fcps-bio4-66","Kwashiorkor differs from marasmus in that it shows:",["Oedema and fatty liver with relatively preserved subcutaneous fat","Severe wasting with no oedema","Normal albumin","Increased appetite only"],"Protein deficiency with adequate calories lowers albumin and causes oedema, while marasmus is global energy deficiency."],["q-fcps-bio4-67","The respiratory quotient of pure carbohydrate oxidation is:",["1.0","0.7","0.8","0.5"],"Carbohydrate gives an RQ of 1.0, fat 0.7 and protein about 0.8."],["q-fcps-bio4-68","Selenium is an essential cofactor for:",["Glutathione peroxidase","Superoxide dismutase","Catalase","Cytochrome oxidase"],"Selenocysteine is part of glutathione peroxidase and the deiodinases."],["q-fcps-bio4-69","Zinc deficiency causes:",["Acrodermatitis enteropathica with poor wound healing","Goitre","Pellagra","Scurvy"],"Zinc is a cofactor for many enzymes, and deficiency causes perioral and acral dermatitis, alopecia, diarrhoea and impaired immunity."]];
